VOWELS = "aeiou"


def _translate_word(word):
    # Rule 1: word begins with a vowel, or starts with "xr" or "yt".
    if word[0] in VOWELS or word.startswith(("xr", "yt")):
        return word + "ay"

    # Find the end of the leading consonant cluster. A "y" after the first
    # letter acts as a vowel (Rule 4), e.g. "rhythm" -> "rh" + "ythm".
    i = 0
    while i < len(word) and word[i] not in VOWELS and not (word[i] == "y" and i > 0):
        i += 1

    # Rule 3: a "qu" at the end of the consonant cluster moves with it.
    if i > 0 and word[i - 1 : i + 1] == "qu":
        i += 1

    return word[i:] + word[:i] + "ay"


def translate(text):
    return " ".join(_translate_word(word) for word in text.split())
